<script setup lang="ts">
import LeadEditor from './LeadEditor.vue'
import LeadDetail from './LeadDetail.vue'
import Results from './Results.vue'
import type { Prospect } from '~/types/prospecting'
import { heat, terminalStage } from '~/utils/prospecting'
import { prospectStages, prospectHeatClasses } from '~/constants/prospecting'
const store = useProspecting()
const { data, ready, blocked, error, notice, query, city, segment, priority, stage, view, today, active, due, filtered, stats, pendingImport } = store
const editor = ref<InstanceType<typeof LeadEditor> | null>(null)
const detail = ref<InstanceType<typeof LeadDetail> | null>(null)
const selectedId = ref('')
const selected = computed(() => data.value.leads.find(lead => lead.id === selectedId.value) || null)
const arrangement = ref('Lista')
const target = ref(30)
const budget = ref(0)
watch(() => data.value.settings, value => { target.value = value.target; budget.value = value.budget }, { immediate: true })
const cities = computed(() => [...new Set(data.value.leads.map(lead => lead.city))].sort())
const segments = computed(() => [...new Set(data.value.leads.map(lead => lead.segment))].sort())
async function open(lead: Prospect) { selectedId.value = lead.id; await nextTick(); detail.value?.open(lead) }
async function importFile(event: Event) { const input = event.target as HTMLInputElement; const file = input.files?.[0]; if (file) await store.prepareImport(file); input.value = '' }
function changeView(value: string) { view.value = value; store.clearFilters() }
</script>
<template>
  <div class="min-h-screen bg-[#f3f6fb] font-body text-[#17253e] [&_input]:max-w-full [&_input]:text-base [&_select]:max-w-full [&_select]:text-base [&_textarea]:text-base [&_p]:break-words">
    <div class="lg:fixed lg:inset-y-0 lg:left-0 lg:w-60"><aside class="flex h-full flex-col bg-[#14243e] px-5 py-6 text-white"><NuxtLink to="/" class="text-3xl font-bold tracking-tight">avyro<span class="text-blue-300">.</span></NuxtLink><p class="mt-2 text-xs uppercase tracking-[0.2em] text-slate-400">Prospecção ativa</p><nav aria-label="Painel de prospecção" class="mt-7 flex flex-wrap gap-2 lg:flex-col"><button v-for="(item, i) in ['Contatos', 'Retornos', 'Resultados', 'Arquivados', 'Configurações']" :key="item" class="flex min-h-11 items-center justify-between gap-4 rounded-lg px-4 py-3 text-left text-sm" :class="view === item ? 'bg-[#2c4162] text-white' : 'text-slate-300 hover:bg-white/10'" :aria-current="view === item ? 'page' : undefined" @click="changeView(item)"><span><span class="mr-3 text-slate-400">0{{ i + 1 }}</span>{{ item }}</span><span v-if="item === 'Retornos' && due.length" class="rounded-full bg-amber-300 px-2 text-xs text-slate-900">{{ due.length }}</span></button></nav><div class="mt-7 hidden rounded-xl border border-white/15 p-4 text-xs leading-6 text-slate-300 lg:mt-auto lg:block">Uma cidade por vez.<br>Uma abordagem com contexto.<br>Um próximo passo registrado.</div></aside></div>
    <main class="px-4 py-7 sm:px-7 lg:ml-60 lg:px-10"><header class="mx-auto flex max-w-[1440px] flex-col justify-between gap-5 sm:flex-row sm:items-center"><div><p class="text-xs text-slate-500">Seu espaço de trabalho / {{ today.split('-').reverse().join('/') }}</p><h1 class="mt-2 text-3xl font-semibold tracking-tight">{{ view === 'Contatos' ? 'Boas conversas começam aqui.' : view }}</h1></div><button :disabled="!ready || blocked" class="min-h-12 rounded-xl bg-[#2458df] px-6 py-3 text-sm font-semibold text-white shadow-sm disabled:opacity-50" @click="editor?.open()">+ Nova empresa</button></header>
      <div class="mx-auto max-w-[1440px]"><p class="mt-5 text-xs leading-6 text-slate-500">Sem login · Dados salvos apenas neste navegador e endereço. Exporte backups para guardar ou transferir seus contatos.</p><div v-if="error" role="alert" class="mt-4 rounded-xl border border-rose-200 bg-rose-50 p-4 text-sm text-rose-800">{{ error }}</div><div v-if="notice" role="status" class="mt-4 flex items-center justify-between gap-4 rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-2 text-sm text-emerald-800"><span>{{ notice }}</span><button aria-label="Dispensar aviso" class="h-11 w-11 shrink-0" @click="notice = ''">✕</button></div>
        <p v-if="!ready" role="status" class="py-20 text-center text-slate-500">Abrindo seus contatos…</p>
        <template v-else>
          <div class="my-7 grid grid-cols-2 gap-3 xl:grid-cols-4"><div v-for="item in [{ label: 'Empresas contatadas', value: `${stats.contacted} / ${data.settings.target}`, sub: 'Sua meta de prospecção' }, { label: 'Respostas recebidas', value: stats.responses, sub: stats.contacted ? `${Math.round(stats.responses / stats.contacted * 100)}% das contatadas` : 'Registre o primeiro contato' }, { label: 'Demonstraram interesse', value: stats.interested, sub: 'Empresas únicas no histórico' }, { label: 'Retornos até hoje', value: due.length, sub: 'Pendentes e sem encerramento' }]" :key="item.label" class="rounded-xl border border-slate-200 bg-white p-4 sm:p-5"><p class="text-xs text-slate-500">{{ item.label }}</p><p class="mt-3 text-2xl font-semibold sm:text-3xl">{{ item.value }}</p><p class="mt-3 text-[11px] leading-5 text-slate-500">{{ item.sub }}</p></div></div>
          <Results v-if="view === 'Resultados'" :leads="data.leads" :settings="data.settings" />
          <div v-else-if="view === 'Configurações'" class="grid gap-6 xl:grid-cols-2"><form class="rounded-2xl border bg-white p-6" @submit.prevent="store.settings({ target, budget }) && (notice = 'Meta e investimento atualizados.')"><h2 class="text-xl font-semibold">Meta e investimento</h2><p class="mt-3 text-sm leading-7 text-slate-500">A conversa de referência propõe começar com 30 empresas. Registre aqui o investimento real da sua prospecção, se houver.</p><label class="mt-5 block text-sm">Meta de empresas contatadas<input v-model.number="target" type="number" min="1" required class="mt-2 min-h-12 w-full rounded-lg border px-3"></label><label class="mt-5 block text-sm">Investimento total informado (R$)<input v-model.number="budget" type="number" min="0" step="0.01" required class="mt-2 min-h-12 w-full rounded-lg border px-3"></label><button :disabled="blocked" class="mt-6 min-h-12 rounded-lg bg-[#2458df] px-5 py-3 text-sm text-white disabled:opacity-50">Salvar configuração</button></form><section class="rounded-2xl border bg-white p-6"><h2 class="text-xl font-semibold">Seus dados, com você</h2><p class="mt-3 text-sm leading-7 text-slate-500">O backup inclui empresas, observações, valores e histórico. Guarde o arquivo em um local seu. Limpar os dados do navegador remove o armazenamento deste painel.</p><div class="mt-6 flex flex-wrap gap-3"><button class="min-h-12 rounded-lg border px-5 py-3 text-sm" @click="store.exportBackup">Exportar backup</button><label class="inline-flex min-h-12 cursor-pointer items-center rounded-lg border px-5 py-3 text-sm">Importar backup<input type="file" accept=".json,application/json" class="sr-only" :disabled="blocked" @change="importFile"></label></div><div v-if="pendingImport" class="mt-6 rounded-xl bg-slate-50 p-5"><h3 class="text-sm font-semibold">Conferir importação</h3><p class="mt-3 text-sm leading-7">{{ pendingImport.leads.length }} empresas no arquivo. Registros com o mesmo identificador serão ignorados; seus contatos atuais serão preservados. Se o painel estiver vazio, a meta e o investimento do backup também serão restaurados.</p><div class="mt-4 flex flex-wrap gap-3"><button class="min-h-11 rounded-lg bg-[#2458df] px-4 text-sm text-white" @click="store.importBackup">Importar novos contatos</button><button class="min-h-11 px-3 text-sm" @click="pendingImport = null">Cancelar</button></div></div></section><section class="rounded-2xl border bg-white p-6 xl:col-span-2"><h2 class="text-xl font-semibold">Critérios da sua estratégia</h2><div class="mt-5 grid gap-6 md:grid-cols-3"><p class="text-sm leading-7"><strong>Quente</strong><br>Negócio ativo, com apresentação profissional, sem site próprio ou apenas Instagram.</p><p class="text-sm leading-7"><strong>Morno</strong><br>Negócio ativo, com um site antigo ou que precisa melhorar.</p><p class="text-sm leading-7"><strong>Revisar ou descartar</strong><br>Confira as informações faltantes. Sinais de abandono sugerem não priorizar; a decisão continua sendo sua.</p></div><p class="mt-5 text-xs leading-6 text-slate-500">Boas avaliações e fotos recentes reforçam a análise. A classificação pode ser ajustada manualmente, sem previsão de venda.</p></section></div>
          <section v-else class="overflow-hidden rounded-2xl border border-slate-200 bg-white"><div class="border-b p-5"><div class="flex flex-col justify-between gap-4 md:flex-row md:items-center"><div><h2 class="text-xl font-semibold">{{ view === 'Retornos' ? 'Quem precisa de um próximo passo?' : view === 'Arquivados' ? 'Contatos arquivados' : 'Sua lista de oportunidades' }}</h2><p class="mt-2 text-xs text-slate-500">{{ filtered.length }} empresas nesta seleção</p></div><div class="flex gap-2" role="group" aria-label="Visualização dos contatos"><button v-for="mode in ['Lista', 'Funil']" :key="mode" :aria-pressed="arrangement === mode" class="min-h-11 rounded-lg border px-4 text-sm" :class="arrangement === mode ? 'bg-slate-100 font-semibold' : ''" @click="arrangement = mode">{{ mode }}</button></div></div><div class="mt-5 grid gap-3 sm:grid-cols-2 xl:grid-cols-[1.4fr_1fr_1fr_1fr_1fr]"><input v-model="query" aria-label="Buscar empresa ou pessoa" type="search" placeholder="Buscar empresa ou pessoa…" class="min-h-12 w-full rounded-lg border border-slate-200 px-3 text-base"><select v-model="city" aria-label="Filtrar cidade" class="min-h-12 rounded-lg border border-slate-200 px-3 text-sm"><option value="">Todas as cidades</option><option v-for="item in cities" :key="item">{{ item }}</option></select><select v-model="segment" aria-label="Filtrar segmento" class="min-h-12 rounded-lg border border-slate-200 px-3 text-sm"><option value="">Todos os segmentos</option><option v-for="item in segments" :key="item">{{ item }}</option></select><select v-model="priority" aria-label="Filtrar prioridade" class="min-h-12 rounded-lg border border-slate-200 px-3 text-sm"><option value="">Todas as prioridades</option><option>Quente</option><option>Morno</option><option>Revisar</option><option>Descartar</option></select><select v-model="stage" aria-label="Filtrar etapa" class="min-h-12 rounded-lg border border-slate-200 px-3 text-sm"><option value="">Todas as etapas</option><option v-for="item in prospectStages" :key="item">{{ item }}</option></select></div><button v-if="query || city || segment || priority || stage" class="mt-2 min-h-11 text-xs text-blue-700 underline" @click="store.clearFilters">Limpar filtros</button></div>
            <div v-if="!filtered.length" class="px-6 py-16 text-center"><p class="text-3xl text-slate-300" aria-hidden="true">↗</p><h3 class="mt-4 text-xl font-semibold">{{ !data.leads.length ? 'Sua primeira empresa começa a lista.' : view === 'Retornos' ? 'Nenhum retorno pendente nesta seleção.' : 'Nenhuma empresa nesta seleção.' }}</h3><p class="mx-auto mt-3 max-w-md text-sm leading-7 text-slate-500">{{ !data.leads.length ? 'Escolha uma cidade, pesquise um segmento e registre o que encontrou antes de iniciar a conversa.' : 'Revise os filtros ou adicione uma nova oportunidade.' }}</p><button v-if="!data.leads.length" :disabled="blocked" class="mt-6 min-h-12 rounded-lg bg-blue-600 px-5 text-sm text-white" @click="editor?.open()">Cadastrar primeira empresa</button></div>
            <div v-else-if="arrangement === 'Lista'" class="divide-y divide-slate-100"><button v-for="lead in filtered" :key="lead.id" class="grid min-h-24 w-full gap-4 p-5 text-left hover:bg-slate-50 sm:grid-cols-[1.6fr_1fr_1fr] xl:grid-cols-[1.5fr_1fr_0.7fr_1fr_1fr]" @click="open(lead)"><div><p class="font-semibold">{{ lead.company }}</p><p class="mt-1 text-xs text-slate-500">{{ lead.person || 'Responsável a identificar' }}</p></div><div><p class="text-sm">{{ lead.segment }}</p><p class="mt-1 text-xs text-slate-500">{{ lead.city }}</p></div><div><span class="inline-block rounded-full border px-3 py-1 text-xs" :class="prospectHeatClasses[heat(lead)]">{{ heat(lead) }}</span></div><div><p class="text-sm">{{ lead.stage }}</p><p class="mt-1 text-xs text-slate-500">{{ lead.websiteStatus }}</p></div><div><p class="text-sm" :class="lead.followUp && lead.followUp < today && !terminalStage(lead.stage) ? 'font-semibold text-amber-700' : ''">{{ lead.followUp && !terminalStage(lead.stage) ? lead.followUp.split('-').reverse().join('/') : 'Sem retorno agendado' }}</p><p class="mt-1 text-xs text-slate-500">{{ lead.nextAction || 'Abrir ficha ↗' }}</p></div></button></div>
            <div v-else class="grid gap-4 bg-slate-50 p-4 md:grid-cols-2 xl:grid-cols-3"><section v-for="column in prospectStages.filter(item => filtered.some(lead => lead.stage === item))" :key="column" class="rounded-xl border border-slate-200 bg-slate-100 p-3"><h3 class="mb-4 flex justify-between text-sm font-semibold">{{ column }} <span class="text-slate-500">{{ filtered.filter(lead => lead.stage === column).length }}</span></h3><button v-for="lead in filtered.filter(item => item.stage === column)" :key="lead.id" class="mb-3 block w-full rounded-lg border bg-white p-4 text-left shadow-sm" @click="open(lead)"><p class="font-semibold">{{ lead.company }}</p><p class="mt-2 text-xs text-slate-500">{{ lead.segment }} · {{ lead.city }}</p><span class="mt-4 inline-block rounded-full border px-3 py-1 text-xs" :class="prospectHeatClasses[heat(lead)]">{{ heat(lead) }}</span><p v-if="lead.followUp && !terminalStage(lead.stage)" class="mt-4 text-xs text-slate-500">Retorno: {{ lead.followUp.split('-').reverse().join('/') }}</p></button></section></div>
          </section>
        </template>
      </div>
    </main>
    <LeadEditor ref="editor" :save="store.save" /><LeadDetail ref="detail" :lead="selected" :log="store.log" @edit="editor?.open($event)" @archive="store.archive" @reopen="store.reopen" />
  </div>
</template>
